it('preserves non-negative integer list limits and rejects other limits', () => {
  const accepted = [0, 1, 200, 201].map(limit => validateMessage({type: 'list_sessions', limit}));
  const rejected = [-1, 1.5, '10', null, true, NaN, Infinity].map(limit =>
    validateMessage({type: 'list_sessions', limit})
  );

  expect({accepted, rejected}).toEqual({
    accepted: [0, 1, 200, 201].map(limit => ({valid: true, data: {type: 'list_sessions', limit}})),
    rejected: Array(7).fill({valid: false, error: expect.stringContaining('limit')}),
  });
});
